const server = http.createServer((req, res) => { const n=(used.get(req.socket)??0)+1; used.set(req.socket,n); req.resume(); req.on("end", () => { if (n>1) { killed++; req.socket.destroy(); return; } res.setHeader("Content-Type","application/json"); res.end("{}"); }); });
await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
const url = `http://127.0.0.1:${(server.address() as any).port}/x`;
let fails=0;
for (let i = 0; i < 8; i++) { try { const r = await fetch(url, { method: "POST", body: "{}", headers: { connection: "close" } }); await r.json(); } catch (e:any) { fails++; console.log(i, e.cause?.code, e.cause?.message); } }
console.log("fails", fails, "killed", killed);
server.closeAllConnections(); server.close();
EOF
